PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS ecosystems (id TEXT PRIMARY KEY,name TEXT NOT NULL,symbol TEXT,description TEXT,website TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS chains (id TEXT PRIMARY KEY,ecosystem_id TEXT, parent_chain_id TEXT, name TEXT NOT NULL,symbol TEXT,chain_type TEXT,chain_id TEXT,native_token_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS protocols (id TEXT PRIMARY KEY,name TEXT NOT NULL,symbol TEXT,description TEXT,website TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS protocol_chains (id TEXT PRIMARY KEY,protocol_id TEXT NOT NULL,chain_id TEXT NOT NULL,status TEXT DEFAULT 'ACTIVE',valid_from INTEGER,valid_to INTEGER,source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens (id TEXT PRIMARY KEY,chain_id TEXT,name TEXT NOT NULL,symbol TEXT,contract_address TEXT,token_standard TEXT,decimals INTEGER,is_native INTEGER DEFAULT 0,representation_type TEXT DEFAULT 'CANONICAL',canonical_token_id TEXT,identity_status TEXT DEFAULT 'UNVERIFIED',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS token_identifiers (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,provider TEXT,external_id TEXT,identifier_type TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS protocol_tokens (id TEXT PRIMARY KEY,protocol_id TEXT NOT NULL,token_id TEXT NOT NULL,relation_type TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT,base_url TEXT,reliability_note TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY,source_id TEXT,title TEXT,document_type TEXT,url TEXT,author TEXT,published_at INTEGER,updated_at_source INTEGER,retrieved_at INTEGER,content_hash TEXT,status TEXT DEFAULT 'ACTIVE',version INTEGER DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY,document_id TEXT,evidence_type TEXT,quote_or_excerpt TEXT,location TEXT,captured_at INTEGER,interpretation TEXT,strength TEXT,conflict_status TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY,object_type TEXT NOT NULL,object_id TEXT NOT NULL,captured_at INTEGER NOT NULL,period TEXT,schema_version TEXT NOT NULL,state TEXT DEFAULT 'VALID',available_at INTEGER,retrieved_at INTEGER,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS ux_snapshot_identity ON snapshots(object_type,object_id,captured_at,COALESCE(period,''),schema_version);
CREATE TABLE IF NOT EXISTS metrics (id TEXT PRIMARY KEY,snapshot_id TEXT NOT NULL,metric_type TEXT NOT NULL,value_num REAL,value_text TEXT,unit TEXT,scope TEXT,source_id TEXT,retrieved_at INTEGER,source_updated_at INTEGER,available_at INTEGER,definition TEXT,status TEXT DEFAULT 'SUCCESS',data_type TEXT DEFAULT 'RAW',data_version TEXT,period_start INTEGER,period_end INTEGER,formula TEXT,inputs_json TEXT,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_metrics_snapshot_type ON metrics(snapshot_id,metric_type);
CREATE TABLE IF NOT EXISTS token_supply_snapshots (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,supply_as_of INTEGER,total_supply REAL,circulating_supply REAL,max_supply REAL,burned_supply REAL,retrieved_at INTEGER,source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS token_allocations (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,category TEXT,amount REAL,percentage REAL,source_id TEXT,as_of INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS vesting_schedules (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,category TEXT,start_at INTEGER,end_at INTEGER,cliff_at INTEGER,frequency TEXT,source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS unlock_schedules (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,unlock_at INTEGER,amount REAL,status TEXT DEFAULT 'SCHEDULED',source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS unlock_events (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,occurred_at INTEGER,planned_amount REAL,actual_amount REAL,status TEXT,source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS emissions (id TEXT PRIMARY KEY,token_id TEXT NOT NULL,occurred_at INTEGER,amount REAL,event_type TEXT,source_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS research (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,title TEXT,body TEXT,status TEXT DEFAULT 'DRAFT',version INTEGER DEFAULT 1,methodology_version TEXT,data_cutoff_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS risks (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,risk_type TEXT,title TEXT,description TEXT,severity TEXT,status TEXT DEFAULT 'OPEN',evidence_strength TEXT,proposed_by TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conclusions (id TEXT PRIMARY KEY,research_id TEXT,category TEXT,title TEXT,body TEXT,status TEXT DEFAULT 'DRAFT',version INTEGER DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS valuations (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,methodology_id TEXT,methodology_version TEXT,period_start INTEGER,period_end INTEGER,universe_json TEXT,inputs_json TEXT,multiples_json TEXT,status TEXT DEFAULT 'DRAFT',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS money_flows (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,flow_type TEXT,amount REAL,unit TEXT,period_start INTEGER,period_end INTEGER,source_id TEXT,methodology_version TEXT,evidence_relation TEXT,status TEXT DEFAULT 'OBSERVED',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS scenarios (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,name TEXT,type TEXT,description TEXT,assumptions_json TEXT,triggers_json TEXT,indicators_json TEXT,expected_effects_json TEXT,risks_json TEXT,horizon TEXT,status TEXT DEFAULT 'DRAFT',methodology_version TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS comparisons (id TEXT PRIMARY KEY,name TEXT,universe_json TEXT,dimensions_json TEXT,results_json TEXT,fairness_status TEXT,methodology_version TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS causal_claims (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,cause TEXT,effect TEXT,mechanism TEXT,direction TEXT,scope TEXT,time_window TEXT,evidence_json TEXT,alternatives_json TEXT,confidence TEXT,status TEXT DEFAULT 'PROPOSED',version INTEGER DEFAULT 1,methodology_version TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS methodologies (id TEXT PRIMARY KEY,name TEXT,version TEXT,description TEXT,definition_json TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS evaluations (id TEXT PRIMARY KEY,research_id TEXT,validation_period TEXT,data_cutoff_at INTEGER,expected_condition TEXT,observed_outcome TEXT,evidence_quality TEXT,reasoning_quality TEXT,methodology_quality TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,event_type TEXT,title TEXT,description TEXT,occurred_at INTEGER,source_id TEXT,evidence_id TEXT,status TEXT DEFAULT 'OBSERVED',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS relationships (id TEXT PRIMARY KEY,from_type TEXT,from_id TEXT,to_type TEXT,to_id TEXT,edge_type TEXT,status TEXT DEFAULT 'ACTIVE',valid_from INTEGER,valid_to INTEGER,source_id TEXT,evidence_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kg_nodes (id TEXT PRIMARY KEY,node_type TEXT,object_id TEXT,label TEXT,status TEXT DEFAULT 'ACTIVE',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS kg_edges (id TEXT PRIMARY KEY,from_node_id TEXT,to_node_id TEXT,edge_type TEXT,status TEXT DEFAULT 'PROPOSED',evidence_id TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS research_projects (id TEXT PRIMARY KEY,name TEXT,status TEXT DEFAULT 'PLANNED',description TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS research_tasks (id TEXT PRIMARY KEY,project_id TEXT,type TEXT,status TEXT DEFAULT 'TODO',title TEXT,description TEXT,depends_on_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS research_sessions (id TEXT PRIMARY KEY,project_id TEXT,started_at INTEGER,ended_at INTEGER,notes TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS learning_records (id TEXT PRIMARY KEY,skill_type TEXT,level TEXT DEFAULT 'NEW',evidence_json TEXT,notes TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mistake_bank (id TEXT PRIMARY KEY,category TEXT,title TEXT,description TEXT,correction TEXT,status TEXT DEFAULT 'OPEN',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY,object_type TEXT,object_id TEXT,outcome TEXT,reasoning_quality TEXT,evidence_quality TEXT,methodology_quality TEXT,lessons TEXT,reviewed_at INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sync_queue (id TEXT PRIMARY KEY,operation TEXT,object_type TEXT,object_id TEXT,payload_json TEXT,base_version INTEGER,status TEXT DEFAULT 'PENDING',retry_count INTEGER DEFAULT 0,next_retry_at INTEGER,last_error TEXT,idempotency_key TEXT UNIQUE,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sync_logs (id TEXT PRIMARY KEY,queue_id TEXT,status TEXT,request_id TEXT,detail TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS backups (id TEXT PRIMARY KEY,created_at INTEGER,app_version TEXT,schema_version TEXT,data_version TEXT,object_count INTEGER,snapshot_count INTEGER,checksum TEXT,size_bytes INTEGER,storage_location TEXT,status TEXT);
CREATE TABLE IF NOT EXISTS automation_jobs (id TEXT PRIMARY KEY,name TEXT,type TEXT,schedule TEXT,enabled INTEGER DEFAULT 0,priority INTEGER DEFAULT 0,parameters_json TEXT,methodology_version TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automation_runs (id TEXT PRIMARY KEY,job_id TEXT,state TEXT,started_at INTEGER,ended_at INTEGER,request_count INTEGER DEFAULT 0,error_count INTEGER DEFAULT 0,detail TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY,type TEXT,object_type TEXT,object_id TEXT,title TEXT,detail TEXT,trigger_json TEXT,status TEXT DEFAULT 'NEW',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,alert_id TEXT,channel TEXT,status TEXT DEFAULT 'PENDING',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS error_logs (id TEXT PRIMARY KEY,request_id TEXT,level TEXT,code TEXT,message TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS review_queue (id TEXT PRIMARY KEY,type TEXT,object_type TEXT,object_id TEXT,title TEXT,payload_json TEXT,status TEXT DEFAULT 'OPEN',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (id TEXT PRIMARY KEY,value_json TEXT,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_snapshots_object_time ON snapshots(object_type,object_id,captured_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_status_time ON alerts(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_object_time ON events(object_type,object_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_research_object ON research(object_type,object_id);
CREATE INDEX IF NOT EXISTS idx_tokens_identity ON tokens(chain_id,contract_address,is_native);
